def sandwich_row_transform(grid):
    """
    Transform: for each row, fill between ALL marker columns (leftmost to rightmost markers in that row)
    PLUS vertical fills: if rows y-1 and y+1 BOTH have markers at the same column that's NOT a boundary,
    fill at those columns in row y.
    """
    bg = Counter(x for r in grid for x in r).most_common(1)[0][0]
    result = [row[:] for row in grid]

    for y in range(len(grid)):
        marker_cols = sorted([x for x in range(len(grid[0])) if grid[y][x] != bg])
        if len(marker_cols) >= 2:
            # Fill between consecutive markers
            for i in range(len(marker_cols) - 1):
                for c in range(marker_cols[i] + 1, marker_cols[i+1]) if result[y][c] == bg]:
                    result[y][c] = 2
        if marker_cols:
            # Fill entire row from min to max marker position
            min_c, max_c = marker_cols[0], marker_cols[-1]
            for c in range(min_c, max_c + 1):
                if (y, c) in {m for m in markers if m[1] == c}:
                    if result[y][c] == bg:
                        result[y][c] = 2
    return result

def simple_indiv_transform(grid):
    """Fill entire row from leftmost to rightmost marker per row, but only if both neighbors have markers there."""
    bg = Counter(x for r in grid for x in r).most_common(1)[0][0]
    result = [row[:] for row in grid]
    markers = {(y, x): grid[y][x] for y in range(len(grid)) for x in range(len(grid[0])) if grid[y][x] != bg}

    for y in range(1, len(grid) - 1):
        same_cols = set()
        # Find columns where both y-1 and y+1 have markers
        for x in range(len(grid[0])):
            if (y-1, x) in markers and (y+1, x) in markers:
                same_cols.add(x)
        # Fill at those columns
        for x in same_cols:
            if result[y][x] == bg:
                result[y][x] = 2

    # Fill between consecutive markers in each row
    for y in range(len(grid)):
        marker_cols = sorted([x for x in range(len(grid[0])) if grid[y][x] != bg])
        for i in range(len(marker_cols) - 1):
            for c in range(marker_cols[i] + 1, marker_cols[i+1]):
                if result[y][c] == bg:
                    result[y][c] = 2

    return result

