def transform(grid):
    from collections import Counter

    # Determine background and foreground/buffer
    c = Counter(x for r in grid for x in r)
    bg = c.most_common(1)[0][0]
    fg_list = sorted([x for x in c if x != bg])
    fg = fg_list[0] if fg_list else 3
    fill_val = 2

    hsz = len(grid[0])
    vsz = len(grid)

    result = [list(row) for row in grid]

    # Find marked rows (rows with at least one fg marker originally)
    marked_rows = set()
    spans = []
    original_marked = set()
    for y in range(vsz):
        markers = [x for x in range(hsz) if result[y][x] == fg]
        original_marked.add(y)
        if markers:
            spans.append((y, min(markers), max(markers)))
            marked_rows.add(y)

    if not spans:
        return result

    # Extreme columns from all spans
    extreme_cols = set()
    for y, span_min, span_max in spans:
        extreme_cols.add(span_min)
        extreme_cols.add(span_max)

    # RULE 1: Horizontal fill for all marked rows
    for y in sorted(marked_rows):
        markers = [x for x in range(hsz) if result[y][x] == fg]
        for i in range(len(markers) - 1):
            for x in range(markers[i] + 1, markers[i+1]):
                if result[y][x] == bg:
                    result[y][x] = fill_val

    # RULE 2: Vertical fill for:
    # a) All marked rows (at extreme columns)
    # b) Gap rows that are sandwiched between marked rows
    for y in range(vsz):
        if y in marked_rows:
            # Marked row: vertical fill at extreme columns
            for x in extreme_cols:
                if result[y][x] == bg:
                    result[y][x] = fill_val
        else:
            # Gap row: only if sandwiched
            above = [m for m in marked_rows if m < y]
            below = [m for m in marked_rows if m > y]
            if above and below:
                for x in extreme_cols:
                    if result[y][x] == bg:
                        result[y][x] = fill_val

    return result

